async fn handle_request(State(state): State<Arc<ServerState>>, req: Request<Body>) -> Response {
    let path = req.uri().path().to_owned();
    let method = req.method().as_str().to_uppercase();
    let query = req.uri().query().map(str::to_owned);

    // Control requests are answered before route lookup and are never counted.
    if let Some(response) = handle_request_counter_control(&method, &path, query.as_deref()) {
        return response;
    }
    record_request(&method, &path, read_request_body(req.into_body()).await);

    for route in &state.routes {
        // Match on method and either exact path or path prefix (route.path is a prefix of the
        // request path, separated by a '/' boundary). This allows a single route registered at
        // "/v1/batches" to match requests to "/v1/batches/abc123" or
        // "/v1/batches/abc123/cancel".
        let path_matches = path == route.path
            || (path.starts_with(route.path) && path.as_bytes().get(route.path.len()) == Some(&b'/'));
        if path_matches && route.method.to_uppercase() == method {
            if let Some(delay_ms) = route.delay_ms {
                tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
            }
            let status = StatusCode::from_u16(route.status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);

            if route.is_streaming {
                // Build SSE body: data: <chunk>\n\n ... data: [DONE]\n\n
                // Note: stream_chunks may be empty for an empty-stream fixture; we still
                // emit `data: [DONE]\n\n` with the correct SSE headers so clients do not hang.
                let ndjson = headers_declare_ndjson(&route.headers);
                let chunks: Vec<String> = route
                    .stream_chunks
                    .iter()
                    .map(|chunk| state.origins.substitute_str(chunk))
                    .collect();
                let body = match route.stream_chunk_delay_ms {
                    Some(delay_ms) if delay_ms > 0 => paced_sse_body(chunks, delay_ms, ndjson),
                    _ => {
                        let mut sse = String::new();
                        for chunk in &chunks {
                            sse.push_str(&frame_stream_event(chunk, ndjson));
                        }
                        if !ndjson {
                            sse.push_str("data: [DONE]\n\n");
                        }
                        Body::from(sse)
                    }
                };

                let mut builder = Response::builder()
                    .status(status)
                    .header(
                        "content-type",
                        if ndjson {
                            "application/x-ndjson"
                        } else {
                            "text/event-stream"
                        },
                    )
                    .header("cache-control", "no-cache");
                for (name, value) in &route.headers {
                    if ndjson && name.eq_ignore_ascii_case("content-type") {
                        continue;
                    }
                    builder = builder.header(name, state.origins.substitute_str(value));
                }
                return builder.body(body).unwrap().into_response();
            }

            let mut builder = Response::builder()
                .status(status)
                .header("content-type", "application/json");
            for (name, value) in &route.headers {
                builder = builder.header(name, state.origins.substitute_str(value));
            }
            let body_bytes = state.origins.substitute_bytes(route.body.clone().into_bytes());
            return builder
                .body(response_body_with_headers(&route.headers, body_bytes))
                .unwrap()
                .into_response();
        }
    }

    // No matching route → 404.
    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .body(Body::from(format!("No mock route for {method} {path}")))
        .unwrap()
        .into_response()
}
fn response_body_with_headers(headers: &[(String, String)], bytes: Vec<u8>) -> Body {
    let declared_length = headers
        .iter()
        .find(|(name, _)| name.eq_ignore_ascii_case("content-length"))
        .and_then(|(_, value)| value.parse::<u64>().ok());
    if declared_length.is_none_or(|length| length <= bytes.len() as u64) {
        return Body::from(bytes);
    }

    // Exact-sized bodies make Hyper reject intentional Content-Length mismatches
    // before writing headers. Stream the bytes with an unknown size, then yield
    // before terminating so the client observes a truncated body, not a connection
    // failure before the response. The delay begins only after the bytes are polled.
    use tokio_stream::StreamExt;
    const TRUNCATED_BODY_CLOSE_DELAY: std::time::Duration = std::time::Duration::from_millis(50);
    let partial = tokio_stream::once(Ok::<_, std::io::Error>(bytes));
    let termination = tokio_stream::once(()).then(|()| async {
        tokio::time::sleep(TRUNCATED_BODY_CLOSE_DELAY).await;
        Err(std::io::Error::new(
            std::io::ErrorKind::UnexpectedEof,
            "fixture response body truncated",
        ))
    });
    Body::from_stream(partial.chain(termination))
}

/// Whether a streaming route declares a newline-delimited JSON body through its content-type
/// header (as Ollama's `/api/chat` sends). Such a stream has no `data:` prefix and no `[DONE]`.
fn headers_declare_ndjson(headers: &[(String, String)]) -> bool {
    headers
        .iter()
        .any(|(name, value)| name.eq_ignore_ascii_case("content-type") && value.to_ascii_lowercase().contains("ndjson"))
}

/// One stream event as the wire frames it: `data: <chunk>` plus a blank line for SSE, or the
/// chunk plus one newline for NDJSON.
fn frame_stream_event(chunk: &str, ndjson: bool) -> String {
    if ndjson {
        format!("{chunk}\n")
    } else {
        format!("data: {chunk}\n\n")
    }
}

/// SSE body that waits `delay_ms` before each chunk, then ends with `data: [DONE]`.
/// The server writes each event as soon as its delay ends, so a client sees the stream
/// arrive over time instead of in one write. The task stops when the client disconnects.
fn paced_sse_body(chunks: Vec<String>, delay_ms: u64, ndjson: bool) -> Body {
    let (sender, receiver) = tokio::sync::mpsc::channel::<Result<Vec<u8>, std::convert::Infallible>>(1);
    tokio::spawn(async move {
        for chunk in chunks {
            tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
            if sender
                .send(Ok(frame_stream_event(&chunk, ndjson).into_bytes()))
                .await
                .is_err()
            {
                return;
            }
        }
        if !ndjson {
            let _ = sender.send(Ok(b"data: [DONE]\n\n".to_vec())).await;
        }
    });
    Body::from_stream(tokio_stream::wrappers::ReceiverStream::new(receiver))
}

